begin;
alter table public.courses drop constraint courses_category_check;
alter table public.courses add constraint courses_category_check check(category in ('شامل','كمي','لفظي','الاختبارات التعليمية','اللغة الإنجليزية','التطوير الذاتي والمهني','الفنون والتصميم'));
alter table public.courses add column group_id text not null default 'exams' check(group_id in ('exams','english','development','arts'));
alter table public.courses add column is_listed boolean not null default true;
alter table public.courses add column sort_order integer not null default 100 check(sort_order between 0 and 10000);
alter table public.courses add column image_path text not null default '' check(char_length(image_path)<=2000 and (image_path='' or image_path ~ '^https://' or image_path ~ '^\./images/courses/[a-zA-Z0-9._-]+\.(webp|png|jpg|jpeg)$'));
alter table public.courses add column details jsonb not null default '{}' check(jsonb_typeof(details)='object' and octet_length(details::text)<20000);
-- Existing focused aptitude courses remain available to enrolled learners and administrators.
update public.courses set is_listed=false where id in ('quantitative','verbal','intensive');
insert into public.courses(id,title,summary,category,level,status,group_id,is_listed,sort_order,image_path,details) values('teacher-competencies','الكفايات التعليمية','استعداد منظم للاختبار التربوي العام، يربط المفاهيم التعليمية بالمواقف الصفية ويطوّر مهارة تحليل الأسئلة واختيار الاستجابة المناسبة.','الاختبارات التعليمية','للمعلمين والخريجين','active','exams',true,1,'./images/courses/teacher-competencies.webp','{"short":"معرفة تربوية تتحول إلى ممارسة واعية.","overview":"تتناول الدورة الأسس التربوية التي يحتاجها الممارس التعليمي، من فهم التعلّم والتخطيط للتدريس إلى التقويم وإدارة البيئة الصفية. وتجمع بين مراجعة المفاهيم وتحليل المواقف والأسئلة التدريبية، لبناء طريقة واعية في الإجابة. يركّز هذا المسار على الجانب التربوي العام؛ ويُناقش احتياج التخصص عند الحجز.","audience":"المعلمون والمعلمات والخريجون الراغبون في الاستعداد للكفايات التعليمية والاختبار التربوي العام.","prerequisites":"معرفة أولية بالمفاهيم التربوية مفيدة، وتُراجع احتياجاتك مع المركز قبل تأكيد الحجز.","topics":["أخلاقيات المهنة والمسؤولية التعليمية","مبادئ التعلّم والفروق الفردية","التخطيط للتدريس واستراتيجياته","إدارة البيئة الصفية والتفاعل","التقويم وتحليل المواقف والأسئلة"],"outcomes":["ربط المفاهيم التربوية بمواقف تعليمية واضحة.","تحليل السؤال وتحديد المبدأ التربوي المرتبط به.","بناء خطة مراجعة تراعي المجالات التي تحتاج إلى تطوير."],"imageAlt":"دفتر تخطيط تربوي وكتب أمام فصل دراسي"}'::jsonb) on conflict(id) do update set title=excluded.title,summary=excluded.summary,category=excluded.category,level=excluded.level,group_id=excluded.group_id,is_listed=true,sort_order=excluded.sort_order,image_path=excluded.image_path,details=excluded.details;
insert into public.courses(id,title,summary,category,level,status,group_id,is_listed,sort_order,image_path,details) values('foundation','اختبار القدرات العامة','مسار متكامل لتأسيس المهارات الكمية واللفظية، وفهم العلاقات والأفكار، والتدرّب على الحل المنظم وإدارة وقت الإجابة.','الاختبارات التعليمية','من التأسيس إلى التدريب','active','exams',true,2,'./images/courses/foundation.webp','{"short":"فهم أعمق، وخطوات حل أوضح.","overview":"تبدأ الدورة ببناء الأساس في التفكير الكمي والفهم اللفظي، ثم تنتقل إلى تطبيقات تساعدك على قراءة السؤال وتحليل معطياته. وتركّز على فهم سبب الإجابة، ومراجعة الأخطاء، واختيار أسلوب الحل المناسب، مع خطة تدريب تجمع بين التأسيس والممارسة والمراجعة.","audience":"طلاب وطالبات المرحلة الثانوية ومن يستعدون لاختبار القدرات العامة أو يرغبون في تطوير أدائهم.","prerequisites":"لا تحتاج إلى خبرة سابقة في استراتيجيات الاختبار؛ تُحدّد نقطة البداية بحسب مستواك.","topics":["العمليات الحسابية والنسب والتناسب","الجبر والهندسة والمقارنات الكمية","العلاقات اللفظية وإكمال الجمل","استيعاب المقروء وتحليل السياق","إدارة الوقت ومراجعة الأخطاء"],"outcomes":["تفكيك السؤال إلى معطيات ومطلوب واضح.","اختيار طريقة حل كمية أو لفظية مناسبة.","تحديد نقاط الضعف وتنظيم المراجعة حولها."],"imageAlt":"أدوات هندسية ورسومات رياضية ودفتر أزرق"}'::jsonb) on conflict(id) do update set title=excluded.title,summary=excluded.summary,category=excluded.category,level=excluded.level,group_id=excluded.group_id,is_listed=true,sort_order=excluded.sort_order,image_path=excluded.image_path,details=excluded.details;
insert into public.courses(id,title,summary,category,level,status,group_id,is_listed,sort_order,image_path,details) values('achievement','الاختبار التحصيلي','مراجعة للمفاهيم الدراسية الأساسية، مع تطبيقات تربط المعلومات وتساعد على الاسترجاع والتحليل والتعامل المنظم مع الأسئلة التحصيلية.','الاختبارات التعليمية','لطلاب المرحلة الثانوية','active','exams',true,3,'./images/courses/achievement.webp','{"short":"اربط المفاهيم، وثبّت أساسك العلمي.","overview":"تساعدك الدورة على تنظيم المادة العلمية وتحويلها إلى محاور مترابطة يسهل مراجعتها. وتشمل مراجعة المفاهيم، وفهم العلاقات والقوانين، وحل تطبيقات متدرجة، ثم تحليل الأخطاء لتوجيه جهدك إلى ما يحتاج إلى تعزيز. يُحدّد المسار والمواد المشمولة بما يناسب تخصصك عند تأكيد الحجز.","audience":"طلاب وطالبات المرحلة الثانوية والخريجون المقبلون على الاختبار التحصيلي.","prerequisites":"دراسة سابقة لمقررات المرحلة الثانوية؛ تُراجع المواد والمسار المطلوبان مع المركز.","topics":["تنظيم محاور المقررات الأساسية","ربط المفاهيم والقوانين وتطبيقاتها","استراتيجيات الاسترجاع والمراجعة","تحليل الأسئلة والتمييز بين البدائل","تطبيقات تدريبية وخطة مراجعة"],"outcomes":["تنظيم المادة العلمية في خريطة مراجعة واضحة.","توظيف المفاهيم والقوانين في أسئلة متنوعة.","تحديد الموضوعات التي تستحق مزيدًا من التدريب."],"imageAlt":"أدوات علمية ونموذج جزيئي وكتب للمراجعة"}'::jsonb) on conflict(id) do update set title=excluded.title,summary=excluded.summary,category=excluded.category,level=excluded.level,group_id=excluded.group_id,is_listed=true,sort_order=excluded.sort_order,image_path=excluded.image_path,details=excluded.details;
insert into public.courses(id,title,summary,category,level,status,group_id,is_listed,sort_order,image_path,details) values('english-foundations','تأسيس اللغة الإنجليزية','بداية متدرجة لبناء المفردات والقواعد والنطق، مع مواقف عملية تنمّي مهارات الاستماع والتحدث والقراءة والكتابة.','اللغة الإنجليزية','للمبتدئين','active','english',true,4,'./images/courses/english-foundations.webp','{"short":"أساس لغوي تستخدمه كل يوم.","overview":"تمنحك الدورة مدخلًا واضحًا إلى اللغة الإنجليزية، يبدأ بالأصوات والمفردات الشائعة وبناء الجملة، ثم ينتقل إلى استخدام اللغة في مواقف يومية بسيطة. تتكامل أنشطة القراءة والاستماع والمحادثة والكتابة لتكوين أساس تستطيع تطويره بثقة في المراحل التالية.","audience":"المبتدئون ومن يرغبون في إعادة بناء أساسهم في اللغة الإنجليزية.","prerequisites":"لا تشترط معرفة متقدمة باللغة. تُراجع نقطة البداية لتناسب خبرتك السابقة.","topics":["الأصوات والنطق والمفردات الأساسية","بناء الجملة والقواعد الأكثر استخدامًا","الاستماع وفهم المحادثات اليومية","التحدث والتعريف بالنفس والتواصل","قراءة النصوص القصيرة والكتابة البسيطة"],"outcomes":["استخدام مفردات وتراكيب مناسبة للمواقف اليومية.","فهم الفكرة العامة في نص أو محادثة قصيرة.","كتابة جمل واضحة وبناء خطة ممارسة مستمرة."],"imageAlt":"حروف إنجليزية وكتب ودفتر لتأسيس اللغة"}'::jsonb) on conflict(id) do update set title=excluded.title,summary=excluded.summary,category=excluded.category,level=excluded.level,group_id=excluded.group_id,is_listed=true,sort_order=excluded.sort_order,image_path=excluded.image_path,details=excluded.details;
insert into public.courses(id,title,summary,category,level,status,group_id,is_listed,sort_order,image_path,details) values('step','اختبار ستيب STEP','استعداد لاختبار كفايات اللغة الإنجليزية، يركّز على فهم المقروء والاستماع والتراكيب اللغوية، مع تدريب على تحليل الأسئلة وإدارة الوقت.','اللغة الإنجليزية','للراغبين في اختبار ستيب','active','english',true,5,'./images/courses/step.webp','{"short":"تدريب لغوي موجّه لهدفك.","overview":"تربط الدورة بين تطوير المهارة اللغوية والتدرّب على التعامل مع أسئلة STEP. وتتناول قراءة النصوص، واستخلاص المعلومات من الاستماع، ومراجعة القواعد والتراكيب في سياقها. كما تساعدك على تمييز البدائل وتحليل أخطائك، لتبني مراجعة تناسب مستواك وهدفك.","audience":"الطلاب والخريجون والموظفون الراغبون في الاستعداد لاختبار STEP.","prerequisites":"معرفة أساسية باللغة الإنجليزية. إذا كنت مبتدئًا تمامًا، تساعدك دورة التأسيس على الاستعداد لهذا المسار.","topics":["استيعاب المقروء وتحديد الفكرة والتفاصيل","الاستماع والتقاط المعلومات الأساسية","القواعد والتراكيب اللغوية في السياق","تحليل البدائل وأنماط الأسئلة","التدريب الزمني ومراجعة الأخطاء"],"outcomes":["قراءة النصوص وتحديد المعلومات المطلوبة بكفاءة.","مراجعة القواعد من خلال استخدامها في السياق.","اختيار خطة تدريب مبنية على احتياجك اللغوي."],"imageAlt":"سماعات ودفتر مفتوح لتدريب الاستماع باللغة الإنجليزية"}'::jsonb) on conflict(id) do update set title=excluded.title,summary=excluded.summary,category=excluded.category,level=excluded.level,group_id=excluded.group_id,is_listed=true,sort_order=excluded.sort_order,image_path=excluded.image_path,details=excluded.details;
insert into public.courses(id,title,summary,category,level,status,group_id,is_listed,sort_order,image_path,details) values('ielts','اختبار آيلتس IELTS','تدريب على مهارات الاستماع والقراءة والكتابة والمحادثة، مع التركيز على فهم المهام وبناء إجابات واضحة تناسب هدفك من اختبار آيلتس.','اللغة الإنجليزية','بحسب مستواك اللغوي','active','english',true,6,'./images/courses/ielts.webp','{"short":"عبّر عن معرفتك بلغة أوضح.","overview":"تجمع الدورة بين تنمية المهارات الأربع والتعرّف على متطلبات مهام IELTS. وتتدرّب على قراءة النصوص، وتنظيم الأفكار في الكتابة، وتطوير الإجابات الشفهية، والتقاط المعلومات في الاستماع. يُحدّد نوع الاختبار الأكاديمي أو العام واحتياجك التدريبي قبل تأكيد الحجز.","audience":"الراغبون في الاستعداد لآيلتس لأهداف الدراسة أو العمل أو متطلبات الجهات المختلفة.","prerequisites":"أساس مناسب في الإنجليزية. تُناقش نقطة البداية ونوع الاختبار والهدف مع المركز.","topics":["مهارات الاستماع وتدوين الملاحظات","استراتيجيات قراءة النصوص","تنظيم الكتابة وبناء الأفكار","المحادثة وتطوير الإجابة الشفهية","فهم المهمة وإدارة وقت الاستجابة"],"outcomes":["فهم المطلوب في كل مهمة قبل البدء بالإجابة.","بناء إجابات مكتوبة وشفهية منظمة.","تحديد أولويات تطوير المهارات الأربع."],"imageAlt":"ميكروفون ودفتر وكتب في بيئة تعلم أكاديمية"}'::jsonb) on conflict(id) do update set title=excluded.title,summary=excluded.summary,category=excluded.category,level=excluded.level,group_id=excluded.group_id,is_listed=true,sort_order=excluded.sort_order,image_path=excluded.image_path,details=excluded.details;
insert into public.courses(id,title,summary,category,level,status,group_id,is_listed,sort_order,image_path,details) values('toefl','اختبار توفل TOEFL','تطوير اللغة الإنجليزية في السياقات الأكاديمية واليومية، مع تدريب موجّه على القراءة والاستماع والكتابة والتحدث استعدادًا لاختبار توفل.','اللغة الإنجليزية','بحسب مستواك اللغوي','active','english',true,7,'./images/courses/toefl.webp','{"short":"استعداد للغة في سياق أكاديمي.","overview":"تركّز الدورة على فهم اللغة واستخدامها في المهام الأكاديمية والتواصلية، من تحليل النصوص والمعلومات المسموعة إلى بناء استجابات مكتوبة وشفهية. وتساعدك على تنظيم الأفكار وإدارة زمن الإجابة. يُراجع نوع اختبار TOEFL وإصداره ومتطلباتك قبل اعتماد الخطة التدريبية.","audience":"الطلاب والخريجون والمهتمون بالدراسة والبرامج التي تطلب اختبار TOEFL.","prerequisites":"معرفة أساسية باللغة الإنجليزية، مع مراجعة مستواك ونوع الاختبار الذي تستعد له.","topics":["قراءة النصوص وتحديد المعنى والعلاقات","الاستماع وتلخيص المعلومات المهمة","بناء الجمل والاستجابات المكتوبة","التحدث وتنظيم الأفكار شفهيًا","مهارات تنفيذ المهام وإدارة الوقت"],"outcomes":["استخلاص المعلومات وتنظيمها من مصادر لغوية متنوعة.","تقديم استجابات واضحة ومترابطة.","توجيه الممارسة وفق مهاراتك واحتياجك للاختبار."],"imageAlt":"حاسوب وكتب أكاديمية وقلم في مساحة دراسة هادئة"}'::jsonb) on conflict(id) do update set title=excluded.title,summary=excluded.summary,category=excluded.category,level=excluded.level,group_id=excluded.group_id,is_listed=true,sort_order=excluded.sort_order,image_path=excluded.image_path,details=excluded.details;
insert into public.courses(id,title,summary,category,level,status,group_id,is_listed,sort_order,image_path,details) values('self-development','تطوير الذات','مهارات عملية لفهم الذات وتحديد الأهداف وتنظيم الوقت، وتطوير التواصل والعادات التي تدعم التعلّم والإنجاز في الحياة اليومية.','التطوير الذاتي والمهني','لجميع المهتمين','active','development',true,8,'./images/courses/self-development.webp','{"short":"وعي بقدراتك، وخطوات قابلة للتطبيق.","overview":"تساعدك الدورة على النظر إلى أهدافك وعاداتك بطريقة عملية، وتحديد ما تستطيع تطويره بخطوات واضحة. وتتضمن أدوات للتخطيط وإدارة الأولويات والتواصل وحل المشكلات، مع تطبيقات تبني منها خطة شخصية قابلة للمراجعة والتحسين.","audience":"من يرغبون في تطوير مهاراتهم الشخصية وتنظيم أهدافهم وعاداتهم اليومية.","prerequisites":"لا توجد متطلبات معرفية سابقة؛ تكفي الرغبة في التطبيق والمراجعة.","topics":["الوعي بالذات وتحديد نقاط القوة","صياغة الأهداف وتحديد الأولويات","إدارة الوقت وبناء العادات","التواصل والاستماع والتعبير","اتخاذ القرار وخطة التطوير الشخصية"],"outcomes":["تحويل هدف عام إلى خطوات واضحة قابلة للمتابعة.","اختيار أدوات مناسبة لإدارة الوقت والأولويات.","بناء خطة تطوير شخصية يمكن مراجعتها."],"imageAlt":"مخطط أسبوعي وقلم ومكعبات خشبية متدرجة"}'::jsonb) on conflict(id) do update set title=excluded.title,summary=excluded.summary,category=excluded.category,level=excluded.level,group_id=excluded.group_id,is_listed=true,sort_order=excluded.sort_order,image_path=excluded.image_path,details=excluded.details;
insert into public.courses(id,title,summary,category,level,status,group_id,is_listed,sort_order,image_path,details) values('professional-development','التطوير المهني','تطوير مهارات التواصل والعمل الجماعي والتخطيط وحل المشكلات، لتقديم أداء مهني منظم والتعامل بفاعلية مع متطلبات بيئة العمل.','التطوير الذاتي والمهني','للخريجين والموظفين','active','development',true,9,'./images/courses/professional-development.webp','{"short":"أداء أكثر تنظيمًا وحضورًا في العمل.","overview":"تركّز الدورة على المهارات المشتركة التي يحتاجها الموظف والخريج في بيئة العمل، من التواصل المهني وإدارة المهام إلى تقديم الأفكار والتعاون مع الفريق. وتتدرّب على مواقف عملية تساعدك على تحديد أولوياتك وتوثيق عملك وبناء خطة لتطوير مسارك المهني.","audience":"الخريجون والباحثون عن عمل والموظفون الراغبون في تطوير مهاراتهم المهنية.","prerequisites":"لا يشترط تخصص محدد. يُستفاد من إحضار أهدافك أو مواقف من تجربتك المهنية.","topics":["التواصل والمراسلات المهنية","إدارة المهام وتحديد الأولويات","العمل الجماعي والتعامل مع الملاحظات","حل المشكلات وعرض الأفكار","بناء خطة للتطوير والمسار المهني"],"outcomes":["تنظيم المهام وتوضيح الأولويات ومتابعة الإنجاز.","عرض الأفكار والتواصل بصياغة مهنية واضحة.","تحديد مهارات مستهدفة وخطوات لتطويرها."],"imageAlt":"ملف مهني وقلم ومخطط بياني على طاولة اجتماعات"}'::jsonb) on conflict(id) do update set title=excluded.title,summary=excluded.summary,category=excluded.category,level=excluded.level,group_id=excluded.group_id,is_listed=true,sort_order=excluded.sort_order,image_path=excluded.image_path,details=excluded.details;
insert into public.courses(id,title,summary,category,level,status,group_id,is_listed,sort_order,image_path,details) values('arabic-calligraphy','الخط العربي','مدخل عملي إلى كتابة الحروف وتوازنها واتصالها، والتعرّف على أدوات الخط وقواعده، وصولًا إلى تكوين كتابي متناسق.','الفنون والتصميم','للمبتدئين والمهتمين','active','arts',true,10,'./images/courses/arabic-calligraphy.webp','{"short":"جمال الحرف يبدأ من أساسه.","overview":"تبدأ الدورة بالتعرّف على أدوات الخط وطريقة استخدامها، ثم تتناول أشكال الحروف ونسبها وعلاقاتها على السطر. ومن خلال تمارين متدرجة، تتعلّم ضبط حركة القلم والمسافات والاتصالات، وتطبّق ما تعلمته في تكوين كتابي بسيط. يُحدّد نوع الخط والأدوات المطلوبة عند تأكيد الحجز.","audience":"المهتمون بالخط العربي وتحسين الكتابة وبناء أساس فني في تشكيل الحروف.","prerequisites":"لا تشترط خبرة سابقة بالخط. يوضّح المركز نوع الخط وقائمة الأدوات قبل البداية.","topics":["التعرّف على أدوات الخط وطريقة الإمساك بها","أشكال الحروف والنسب الأساسية","حركة القلم وتوازن السماكات","الاتصالات والمسافات وتنظيم السطر","تطبيق كتابي ومراجعة التكوين"],"outcomes":["استخدام أدوات الخط بطريقة مناسبة للممارسة.","ملاحظة النسب والاتصالات وتصحيحها تدريجيًا.","تنفيذ تكوين كتابي أولي بتوازن أفضل."],"imageAlt":"أقلام قصب ومحبرة وتمارين خط على ورق عاجي"}'::jsonb) on conflict(id) do update set title=excluded.title,summary=excluded.summary,category=excluded.category,level=excluded.level,group_id=excluded.group_id,is_listed=true,sort_order=excluded.sort_order,image_path=excluded.image_path,details=excluded.details;
insert into public.courses(id,title,summary,category,level,status,group_id,is_listed,sort_order,image_path,details) values('interior-design','أساسيات الديكور والتصميم','تأسيس في مبادئ تنسيق الفراغات والألوان والخامات والإضاءة، مع تطبيقات تساعد على تحويل الفكرة إلى تصور بصري متماسك.','الفنون والتصميم','للمبتدئين','active','arts',true,11,'./images/courses/interior-design.webp','{"short":"من الفكرة إلى مساحة متوازنة.","overview":"تعرّفك الدورة على العلاقة بين وظيفة المكان وجماله، وكيفية قراءة الفراغ وتوزيع عناصره واختيار ألوانه وخاماته. وتتدرّب على إعداد لوحة إلهام وتصور أولي يجمع الأثاث والإضاءة والتفاصيل ضمن فكرة واحدة، لتبني أساسًا في التفكير التصميمي وتنسيق المساحات.","audience":"المبتدئون والمهتمون بالديكور وتنسيق المساحات وبناء أساس في التصميم الداخلي.","prerequisites":"لا تحتاج إلى خبرة احترافية أو برنامج تصميم محدد؛ تُوضح متطلبات التطبيقات قبل الحجز.","topics":["مبادئ التكوين والتوازن في الفراغ","قراءة الاحتياج وتوزيع العناصر","تنسيق الألوان والخامات","دور الإضاءة والأثاث والتفاصيل","لوحة الإلهام والتصور التصميمي الأولي"],"outcomes":["قراءة الفراغ وربط اختياراتك بوظيفته.","تنسيق مجموعة ألوان وخامات متجانسة.","تقديم تصور أولي واضح لفكرة تصميمية."],"imageAlt":"عينات خشب وحجر وقماش مع مخطط تصميم داخلي"}'::jsonb) on conflict(id) do update set title=excluded.title,summary=excluded.summary,category=excluded.category,level=excluded.level,group_id=excluded.group_id,is_listed=true,sort_order=excluded.sort_order,image_path=excluded.image_path,details=excluded.details;
insert into public.courses(id,title,summary,category,level,status,group_id,is_listed,sort_order,image_path,details) values('drawing-painting','أساسيات الرسم والفن التشكيلي','تأسيس عملي في الملاحظة والخط والنسب والظل والنور واللون، لتطوير التعبير البصري وتنفيذ أعمال فنية أولية بأسلوب واعٍ.','الفنون والتصميم','للمبتدئين','active','arts',true,12,'./images/courses/drawing-painting.webp','{"short":"تعلّم أن ترى، ثم ارسم ما تراه.","overview":"تبدأ الدورة بتدريب العين على ملاحظة الأشكال والعلاقات، ثم تنتقل إلى بناء الرسم وتوزيع القيم الضوئية والتعرّف على اللون والتكوين. وتجمع بين تمارين فنية متدرجة وتطبيق يجمع المهارات الأساسية، مع الاهتمام بالممارسة وفهم الاختيارات البصرية.","audience":"المبتدئون والهواة الراغبون في تأسيس مهارات الرسم والتعبير التشكيلي.","prerequisites":"لا توجد خبرة فنية مطلوبة. تُشارك قائمة الأدوات والخامات قبل بدء الدورة.","topics":["الملاحظة والخط والأشكال الأساسية","النسب والعلاقات والمنظور الأولي","الظل والنور والقيم البصرية","مبادئ اللون والتكوين الفني","تطبيق تشكيلي ومراجعة العمل"],"outcomes":["رسم أشكال وعلاقات بنسب أكثر اتزانًا.","استخدام الظل والنور لإظهار الحجم.","تنفيذ عمل أولي يجمع مبادئ الرسم والتكوين."],"imageAlt":"أقلام فحم وفرش ورسم لأشكال هندسية على ورق"}'::jsonb) on conflict(id) do update set title=excluded.title,summary=excluded.summary,category=excluded.category,level=excluded.level,group_id=excluded.group_id,is_listed=true,sort_order=excluded.sort_order,image_path=excluded.image_path,details=excluded.details;
insert into public.courses(id,title,summary,category,level,status,group_id,is_listed,sort_order,image_path,details) values('digital-art','الفن الرقمي','مدخل إلى الرسم الرقمي واستخدام الطبقات والفرش والألوان، لبناء عمل بصري من الرسم الأولي حتى الإخراج النهائي.','الفنون والتصميم','تأسيسي','active','arts',true,13,'./images/courses/digital-art.webp','{"short":"أدوات رقمية، وتعبير يحمل فكرتك.","overview":"تعرّفك الدورة على بيئة العمل الرقمي وأدواتها، ثم تتناول تنظيم الطبقات واختيار الفرش وبناء اللون والإضاءة. ومن خلال تطبيق متدرج، تنتقل من تخطيط الفكرة إلى تطويرها وإخراجها بصيغة مناسبة للعرض. يُحدد البرنامج والجهاز المناسبان للتطبيق قبل تأكيد الحجز.","audience":"المهتمون بالرسم الرقمي والهواة الراغبون في تحويل أفكارهم إلى أعمال بصرية رقمية.","prerequisites":"إلمام أساسي باستخدام الحاسوب أو الجهاز اللوحي؛ تُراجع متطلبات البرنامج والأدوات مع المركز.","topics":["مساحة العمل والأدوات وإعداد الملف","الطبقات والفرش وتنظيم الرسم","الرسم الأولي وتطوير التكوين","اللون والإضاءة والملمس الرقمي","إنهاء العمل وتصديره للعرض"],"outcomes":["إعداد ملف وتنظيم طبقاته بطريقة واضحة.","توظيف الفرش والألوان في بناء عمل رقمي.","إخراج مشروع أولي بصيغة مناسبة للعرض."],"imageAlt":"جهاز رسم رقمي وقلم مع عمل نباتي تجريدي بألوان هادئة"}'::jsonb) on conflict(id) do update set title=excluded.title,summary=excluded.summary,category=excluded.category,level=excluded.level,group_id=excluded.group_id,is_listed=true,sort_order=excluded.sort_order,image_path=excluded.image_path,details=excluded.details;
-- Booking and confirmation are handled by the center on WhatsApp. Admin enrollment remains protected and available.
create or replace function public.request_enrollment(p_course text) returns void language plpgsql security definer set search_path='' as $$begin raise exception 'BOOKING_VIA_WHATSAPP';end$$;
notify pgrst, 'reload schema';
commit;
